CREATE INDEX daily_choices_date_completion_schedule_order
  ON daily_choices (
    choice_date, is_completed, COALESCE(scheduled_minute, -1),
    priority, creation_sequence
  );

CREATE UNIQUE INDEX daily_choice_path_steps_one_root
  ON daily_choice_path_steps (daily_choice_id)
  WHERE previous_step_id IS NULL;

CREATE UNIQUE INDEX daily_choice_path_steps_one_successor
  ON daily_choice_path_steps (daily_choice_id, previous_step_id)
  WHERE previous_step_id IS NOT NULL;

CREATE TRIGGER intentions_fts_after_insert
AFTER INSERT ON intentions
BEGIN
  INSERT INTO intention_titles_fts(rowid, title_search_key)
  VALUES (new.rowid, new.title_search_key);
END;

CREATE TRIGGER intentions_fts_after_update_search_content
AFTER UPDATE ON intentions
BEGIN
  INSERT INTO intention_titles_fts(
    intention_titles_fts, rowid, title_search_key
  ) VALUES ('delete', old.rowid, old.title_search_key);
  INSERT INTO intention_titles_fts(rowid, title_search_key)
  VALUES (new.rowid, new.title_search_key);
END;

CREATE TRIGGER intentions_fts_after_delete
AFTER DELETE ON intentions
BEGIN
  INSERT INTO intention_titles_fts(
    intention_titles_fts, rowid, title_search_key
  ) VALUES ('delete', old.rowid, old.title_search_key);
END;

